session_start();include('check-login.php');include('dbstring.php');include_once('department-result-workflow-utils.php');if(!drw_is_admin()){http_response_code(403);exit('Administrator access required.');}drw_ensure_tables($con);$msg='';$actor=isset($_SESSION['USERID'])?$_SESSION['USERID']:'';
