$deps=array();$r=mysqli_query($con,"SELECT departmentid,departmentname FROM tbldepartment WHERE status='active' ORDER BY departmentname");if($r)while($x=mysqli_fetch_assoc($r))$deps[]=$x;$teachers=array();$r=mysqli_query($con,"SELECT userid,CONCAT_WS(' ',firstname,othernames,surname) name FROM tblsystemuser WHERE systemtype='Teacher' AND status='active' ORDER BY firstname,surname");if($r)while($x=mysqli_fetch_assoc($r))$teachers[]=$x;$subjects=array();$r=mysqli_query($con,"SELECT sc.classificationid,CONCAT(sub.subject,' — ',COALESCE(ce.class_name,'')) name FROM tblsubjectclassification sc INNER JOIN tblsubject sub ON sub.subjectid=sc.subjectid LEFT JOIN tblclassentry ce ON ce.class_entryid=sc.classid ORDER BY sub.subject,ce.class_name");if($r)while($x=mysqli_fetch_assoc($r))$subjects[]=$x;
