<!doctype html><html><head><?php include('links.php');?><title>Bulk Department Assignment</title><style>body{background:#f4f8fb;font-family:Arial;color:#17314b}.dba{max-width:1050px;margin:25px auto;background:#fff;padding:24px;border-radius:16px}.dba-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.dba section{border:1px solid #dbe6ee;border-radius:12px;padding:16px}.dba select{width:100%;padding:10px;background:#fff;color:#102a43;border:2px solid #7893aa;border-radius:7px}.choices{max-height:330px;overflow:auto;margin:12px 0;border:1px solid #dbe6ee;border-radius:8px}.choice{display:block;padding:10px;border-bottom:1px solid #edf2f6}.choice input{width:18px;height:18px;vertical-align:middle;margin-right:8px}.dba button{background:#087443;color:#fff;border:0;border-radius:8px;padding:11px 14px;font-weight:bold}@media(max-width:700px){.dba{margin:8px;padding:14px}.dba-grid{grid-template-columns:1fr}}</style></head><body><main class="dba"><p><a href="department-management.php">← Department setup</a></p><h1>Bulk Department Assignment</h1><p>Tick as many teachers or subjects as needed, then assign them to one department.</p><?php if($msg!=='')echo '<p>'.dba($msg).'</p>';?><div class="dba-grid"><section><h2>Assign Teachers</h2><form method="post"><select name="departmentid" required><option value="">Choose department</option><?php foreach($deps as $d){?><option value="<?php echo dba($d['departmentid']);?>"><?php echo dba($d['departmentname']);?></option><?php }?></select><div class="choices"><?php foreach($teachers as $t){?><label class="choice"><input type="checkbox" name="teacherids[]" value="<?php echo dba($t['userid']);?>"><?php echo dba($t['name']);?></label><?php }?></div><button name="assign_teachers">Assign Selected Teachers</button></form></section><section><h2>Assign Subjects</h2><form method="post"><select name="departmentid" required><option value="">Choose department</option><?php foreach($deps as $d){?><option value="<?php echo dba($d['departmentid']);?>"><?php echo dba($d['departmentname']);?></option><?php }?></select><div class="choices"><?php foreach($subjects as $s){?><label class="choice"><input type="checkbox" name="classificationids[]" value="<?php echo dba($s['classificationid']);?>"><?php echo dba($s['name']);?></label><?php }?></div><button name="assign_subjects">Assign Selected Subjects</button></form></section></div></main></body></html>
